-- Café Fausse schema (generated by: flask init-db; exported with pg_dump --schema-only)
-- For reference only — the app creates these tables itself.


CREATE TABLE public.customers (
    customer_id integer NOT NULL,
    customer_name character varying(120),
    email character varying(254) NOT NULL,
    phone_number character varying(30),
    newsletter_signup boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE SEQUENCE public.customers_customer_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.customers_customer_id_seq OWNED BY public.customers.customer_id;

CREATE TABLE public.reservations (
    reservation_id integer NOT NULL,
    customer_id integer NOT NULL,
    time_slot timestamp without time zone NOT NULL,
    table_number smallint NOT NULL,
    guest_count smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_guest_count_range CHECK (((guest_count >= 1) AND (guest_count <= 8))),
    CONSTRAINT ck_table_number_range CHECK (((table_number >= 1) AND (table_number <= 30)))
);

CREATE SEQUENCE public.reservations_reservation_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.reservations_reservation_id_seq OWNED BY public.reservations.reservation_id;

ALTER TABLE ONLY public.customers ALTER COLUMN customer_id SET DEFAULT nextval('public.customers_customer_id_seq'::regclass);

ALTER TABLE ONLY public.reservations ALTER COLUMN reservation_id SET DEFAULT nextval('public.reservations_reservation_id_seq'::regclass);

ALTER TABLE ONLY public.customers
    ADD CONSTRAINT customers_email_key UNIQUE (email);

ALTER TABLE ONLY public.customers
    ADD CONSTRAINT customers_pkey PRIMARY KEY (customer_id);

ALTER TABLE ONLY public.reservations
    ADD CONSTRAINT reservations_pkey PRIMARY KEY (reservation_id);

ALTER TABLE ONLY public.reservations
    ADD CONSTRAINT uq_reservation_customer_slot UNIQUE (customer_id, time_slot);

ALTER TABLE ONLY public.reservations
    ADD CONSTRAINT uq_reservation_slot_table UNIQUE (time_slot, table_number);

ALTER TABLE ONLY public.reservations
    ADD CONSTRAINT reservations_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id) ON DELETE CASCADE;

